using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation values
        // or mutable defaults. Use a fixed seed date instead of DateTime.UtcNow.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }  }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfAppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: Cosmos provider now uses "$type" instead of
        // "Discriminator" by default. For existing documents that already store
        // "Discriminator", explicitly configure the property name to preserve
        // backward compatibility.
        modelBuilder.Entity<Product>(b =>
        {
            b.HasDiscriminator<string>("Discriminator")
             .HasValue<Product>("Product")
             .HasValue<DiscountedProduct>("DiscountedProduct");

            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

class DiscountedProduct : Product
{
    public decimal Discount { get; set; }
}

// --- Cosmos DB query service demonstrating sync → async migration ---
// EF Core 9 breaking change: Synchronous I/O on Cosmos provider is no longer
// supported and throws InvalidOperationException. All queries must use async.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 - sync, now broken in EF Core 9):
    // public List<Product> GetProducts() => _db.Products.ToList();

    // AFTER (EF Core 9 - must use async):
    public async Task<List<Product>> GetProductsAsync()
    {
        return await _db.Products.ToListAsync();
    }

    public async Task<Product?> GetProductByIdAsync(string id)
    {
        return await _db.Products.FirstOrDefaultAsync(p => p.Id == id);
    }
}

